#[verus::external]
fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate a result vector of the same length as `s`
    let mut result = Vec::with_capacity(s.len());
    // Iterate through each character in the input
    for &c in s.iter() {
        // If it's an ASCII uppercase letter, convert to lowercase,
        // otherwise leave it unchanged
        if c.is_ascii_uppercase() {
            result.push(c.to_ascii_lowercase());
        } else {
            result.push(c);
        }
    }
    result
}